SELECT COALESCE(flt12_book_month_id, rownum) AS book_month_id , flt12_account_id AS account_id , flt12_account_no AS account_no , TO_CHAR(flt12_book_date, 'YYYY-MM-DD') AS book_date , flt12_item_type AS item_type , flt12_item_type_nm AS item_type_name , flt12_item_nm AS item_name , flt12_item_cd AS item_code , flt12_book_qty AS book_qty , flt12_book_amt AS book_amt , flt12_stk_price_yn = 'true' AS stk_price_yn FROM ( SELECT ROW_NUMBER() OVER () AS rownum , flt12_book_month_id AS flt12_book_month_id , flt11_company_id AS flt12_company_id , flt11_person_id AS flt12_person_id , flt11_account_id AS flt12_account_id , flt11_item_nm AS flt12_item_nm , flt11_item_type AS flt12_item_type , flt11_book_date AS flt12_book_date , flt12_book_amt AS flt12_book_amt , flt11_book_qty AS flt12_book_qty , flt05_item_type_nm AS flt12_item_type_nm , COALESCE(flt05_stk_price_yn,'false') AS flt12_stk_price_yn , TO_DECRYPTS(flt03_account_no) || ' (' || sys15_corp_nm || ')' AS flt12_account_no , flt11_item_cd AS flt12_item_cd FROM flt11_book INNER JOIN flt03_account ON flt03_account_id = flt11_account_id INNER JOIN sys15_corp ON sys15_corp_id = flt03_corp_id INNER JOIN flt05_item_type ON ( flt05_company_id = flt11_company_id AND flt05_item_type_cd = flt11_item_type AND flt05_start_date = ( SELECT MAX(flt05_start_date) FROM flt05_item_type WHERE flt05_company_id = flt11_company_id AND flt05_item_type_cd = flt11_item_type AND flt05_start_date <= flt11_book_date ) ) LEFT OUTER JOIN flt12_book_month ON ( flt12_company_id = flt11_company_id AND flt12_person_id = flt11_person_id AND flt12_account_id = flt11_account_id AND flt12_item_type = flt11_item_type AND ( ( COALESCE(flt05_stk_price_yn,'false') = 'true' AND flt12_item_cd = flt11_item_cd ) OR ( COALESCE(flt05_stk_price_yn,'false') != 'true' AND flt12_item_nm = flt11_item_nm ) ) AND flt12_book_date = flt11_book_date ) WHERE flt11_company_id = #{companyId} AND flt11_person_id = #{personId} AND flt11_book_date = f_get_biz_date(flt11_company_id, f_get_last_day(flt11_book_date),'-0') AND flt11_book_date BETWEEN CAST(#{startDate} AS date) AND CAST(#{closeDate} AS date) AND flt11_item_type != '99' /*(99:예치금)제외*/ AND flt11_book_qty != 0
AND flt11_account_id = #{accountId}
AND flt03_family_relate_cd = '1'
) a WHERE 1=1
AND UPPER(CONCAT(flt12_item_type_nm, flt12_item_nm, flt12_item_cd)) LIKE UPPER(#{searchText})
ORDER BY flt12_account_no, flt12_book_date, flt12_item_type, flt12_item_nm collate "ko_KR.utf8" asc

SELECT COUNT(*)
  FROM flt12_book_month
 WHERE flt12_book_month_id = #{bookMonthId}
   AND flt12_company_id    = #{companyId}
   AND flt12_person_id     = #{personId}

SELECT flt12_book_month_id AS book_month_id , flt12_company_id AS company_id , flt12_person_id AS person_id , flt12_account_id AS account_id , flt12_item_nm AS item_name , flt12_item_type AS item_type , TO_CHAR(flt12_book_date, 'YYYY-MM-DD') AS book_date , flt12_book_amt AS book_amt , flt12_item_cd AS item_code , flt12_stk_price_yn AS stk_price_yn FROM ( SELECT COALESCE(flt12_book_month_id, f_create_seq()) as flt12_book_month_id , flt11_company_id as flt12_company_id , flt11_person_id as flt12_person_id , flt11_account_id as flt12_account_id , flt11_item_nm as flt12_item_nm , flt11_item_type as flt12_item_type , flt11_book_date as flt12_book_date , CASE WHEN #{type} = '1' THEN flt11_pur_amt ELSE (CASE WHEN COALESCE(flt05_stk_price_yn,'false') != 'true' THEN null ELSE flt11_book_qty * f_get_price_stk(flt11_book_date, flt11_item_cd) END) END as flt12_book_amt , flt11_item_cd as flt12_item_cd , COALESCE(flt05_stk_price_yn,'false') as flt12_stk_price_yn FROM flt11_book INNER JOIN flt03_account ON flt03_account_id = flt11_account_id INNER JOIN flt05_item_type ON ( flt05_company_id = flt11_company_id AND flt05_item_type_cd = flt11_item_type AND flt05_start_date = ( SELECT MAX(flt05_start_date) FROM flt05_item_type WHERE flt05_company_id = flt11_company_id AND flt05_item_type_cd = flt11_item_type AND flt05_start_date <= flt11_book_date ) ) LEFT OUTER JOIN flt12_book_month ON ( flt12_company_id = flt11_company_id AND flt12_person_id = flt11_person_id AND flt12_account_id = flt11_account_id AND flt12_item_type = flt11_item_type AND ( ( COALESCE(flt05_stk_price_yn,'false') = 'true' AND flt12_item_cd = flt11_item_cd ) OR ( COALESCE(flt05_stk_price_yn,'false') != 'true' AND flt12_item_nm = flt11_item_nm ) ) AND flt12_book_date = flt11_book_date ) WHERE flt11_company_id = #{companyId} AND flt11_person_id = #{personId} AND flt11_book_date = f_get_biz_date(flt11_company_id, f_get_last_day(flt11_book_date),'-0') AND flt11_book_date BETWEEN CAST(#{startDate} AS date) AND CAST(#{closeDate} AS date) AND flt11_item_type != '99' /*(99:예치금)제외*/ AND flt11_book_qty > 0 AND flt12_book_amt IS NULL AND UPPER(CONCAT(flt05_item_type_nm, flt11_item_nm, flt11_item_cd)) LIKE UPPER(#{searchText})
AND flt11_account_id = #{accountId}
) t WHERE flt12_book_amt IS NOT NULL

mapper.update:
UPDATE flt12_book_month
   SET flt12_book_amt = #{bookAmt}
 WHERE flt12_book_month_id = #{bookMonthId}
   AND flt12_company_id    = #{companyId}
   AND flt12_person_id     = #{personId}

UPDATE flt11_book
   SET flt11_book_amt = #{bookAmt}
 WHERE flt11_company_id = #{companyId}
   AND flt11_person_id  = #{personId}
   AND flt11_account_id = #{accountId}
   AND flt11_item_type  = #{itemType}
   AND ( ( #{stkPriceYn}  = 'true' AND flt11_item_cd = #{itemCode} ) OR
         ( #{stkPriceYn} != 'true' AND flt11_item_nm = #{itemName} ) )
   AND flt11_book_date  = CAST(#{bookDate} AS date)
